#!/usr/bin/env bash\nset -euo pipefail\n\n# Initialize Terraform without remote backend (offline)\nterraform init -backend=false > /dev/null\n\n# Validate the configuration syntax\nterraform validate\n\n# Generate a plan without applying\nterraform plan -input=false -out=plan.out > plan.txt\n\n# Verify that the plan includes the S3 bucket resource\nif grep -q "aws_s3_bucket.safehouse" plan.txt; then\n  echo "Test passed: S3 bucket is planned."\n  exit 0\nelse\n  echo "Test failed: S3 bucket not found in plan."\n  exit 1\nfi\n
